/* Kasil Devlog: authenticated requests must never use the offline cache.
 * 작성자: 송예찬
 * Overrides Chirpy 7.6.0 at the same theme source path.
 */
"use strict";
importScripts("./assets/js/data/swconf.js");

const CACHE_PREFIX = "chirpy-";
const cacheName = swconf.cacheName ? `${swconf.cacheName}-auth-v1` : null;
const siteBase = new URL("./", self.location.href).pathname;
const adminPath = `${siteBase}admin/`;

function canCacheRequest(request) {
  const url = new URL(request.url);
  if (swconf.purge || request.method !== "GET") return false;
  if (url.origin !== self.location.origin) return false;
  if (request.headers.has("authorization") || request.headers.has("range")) return false;
  if (request.cache === "no-store" || request.cache === "no-cache" || request.cache === "reload") return false;
  if (url.pathname === adminPath.slice(0, -1) || url.pathname.startsWith(adminPath)) return false;
  const deny = swconf.interceptor || {};
  if ((deny.paths || []).some(path => url.pathname.startsWith(path))) return false;
  if ((deny.urlPrefixes || []).some(prefix => url.href.startsWith(prefix))) return false;
  return true;
}

function canCacheResponse(response) {
  return response.ok && response.type !== "opaque" &&
    !/\b(?:no-store|private)\b/i.test(response.headers.get("cache-control") || "");
}

self.addEventListener("install", event => {
  event.waitUntil((async () => {
    if (!swconf.purge) {
      const cache = await caches.open(cacheName);
      const resources = (swconf.resources || []).filter(path =>
        canCacheRequest(new Request(new URL(path, self.location.href))));
      await cache.addAll(resources);
    }
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", event => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter(key => key.startsWith(CACHE_PREFIX) &&
      (swconf.purge || key !== cacheName)).map(key => caches.delete(key)));
    await self.clients.claim();
  })());
});

self.addEventListener("message", event => {
  if (event.data === "SKIP_WAITING") self.skipWaiting();
});

self.addEventListener("fetch", event => {
  // Check before looking up cached entries. Even an old cached 401 must be ignored.
  if (!canCacheRequest(event.request)) return;
  event.respondWith((async () => {
    const cache = await caches.open(cacheName);
    const url = new URL(event.request.url);
    const freshContent = event.request.mode === "navigate" ||
      (event.request.headers.get("accept") || "").includes("text/html") ||
      url.pathname.endsWith("/search.json");
    if (freshContent) {
      // A published post must appear on the next visit, even before a new worker activates.
      try {
        const response = await fetch(event.request, { cache: "no-cache" });
        if (canCacheResponse(response)) {
          event.waitUntil(cache.put(event.request, response.clone()).catch(() => {}));
        }
        return response;
      } catch (error) {
        const offline = await cache.match(event.request);
        if (offline && canCacheResponse(offline)) return offline;
        throw error;
      }
    }
    const cached = await cache.match(event.request);
    if (cached && canCacheResponse(cached)) return cached;
    const response = await fetch(event.request);
    if (canCacheResponse(response)) {
      const copy = response.clone();
      event.waitUntil(cache.put(event.request, copy).catch(() => {}));
    }
    return response;
  })());
});
